#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

import argparse
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from source_fixture import commit, parse_env, run


REPOSITORY = "https://gitlab.freedesktop.org/mesa/mesa.git"
GUEST_SERIES = "tools/rootfs/vulkan/patches/mesa"
PROTOCOL_SERIES = "tools/rootfs/vulkan/patches/venus-protocol"
VULKAN_SOURCES = "tools/rootfs/vulkan/sources.tsv"
CODEC = "src/virtio/venus-protocol"

# Stands in for venus-protocol's generator: the codec depends on the
# protocol source's extension list and on the registry it is given.
FAKE_GENERATOR = '''\
import argparse
import hashlib
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("--outdir", type=Path, required=True)
parser.add_argument("--registry", type=Path, required=True)
parser.add_argument("--banner", type=Path, required=True)
args = parser.parse_args()
extensions = (Path(__file__).resolve().parent / "extensions.txt").read_text()
registry = hashlib.sha256(args.registry.read_bytes()).hexdigest()
(args.outdir / "vn_protocol_driver.h").write_text(
    args.banner.read_text() + '#include "vn_protocol_driver_types.h"\\n'
)
(args.outdir / "vn_protocol_driver_types.h").write_text(
    "/* This file is generated by venus-protocol.  See vn_protocol_driver.h. */\\n"
    f"/* registry {registry} */\\n" + extensions
)
'''


def export(scripts: Path, source: Path, base: str, directory: Path, *tree: str) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    run(
        sys.executable, "-B", str(scripts / "patch_series.py"), "export",
        "--source", str(source), "--base", base, "--head", "HEAD",
        "--series-dir", str(directory), *tree,
    )


def write_protocol(root: Path, scripts: Path) -> tuple[Path, str]:
    """A venus-protocol replay and the protocol series it was replayed from."""
    protocol = root / "protocol"
    run("git", "init", "-q", str(protocol))
    commit(protocol, "vn_protocol.py", FAKE_GENERATOR, "fixture protocol", 1700000000)
    base = run("git", "rev-parse", "HEAD", cwd=protocol)
    commit(protocol, "extensions.txt", "VK_one\n", "protocol: fixture topic", 1700000010)
    export(scripts, protocol, base, root / PROTOCOL_SERIES, "--tree")
    return protocol, base


def write_headers(root: Path) -> Path:
    """A Vulkan-Headers checkout and the source table that pins it."""
    headers = root / "headers"
    run("git", "init", "-q", str(headers))
    commit(headers, "registry/vk.xml", "<registry/>\n", "fixture registry", 1700000000)
    head = run("git", "rev-parse", "HEAD", cwd=headers)
    tree = run("git", "rev-parse", "HEAD^{tree}", cwd=headers)
    (root / VULKAN_SOURCES).write_text(
        "# SPDX-License-Identifier: GPL-2.0-or-later\n"
        "component\trepository\tbase_commit\tbase_tree\trelease_ref\t"
        "release_object\tseries\n"
        f"vulkan-headers\thttps://example.invalid/Vulkan-Headers.git\t{head}\t"
        f"{tree}\tfixture\t{head}\t-\n"
    )
    return headers


def write_fixture(
    source_root: Path,
    android_root: Path,
    topic: Path,
    verifier: Path,
    generator: Path,
) -> tuple[str, str, Path, Path, str]:
    scripts = verifier.parents[3] / "scripts"
    fixture_scripts = source_root / "scripts"
    fixture_scripts.mkdir()
    shutil.copy2(scripts / "patch_series.py", fixture_scripts / "patch_series.py")
    protocol, protocol_base = write_protocol(source_root, fixture_scripts)
    headers = write_headers(source_root)

    run("git", "init", "-q", str(topic))
    run("git", "switch", "-q", "-c", "kernarium-android17", cwd=topic)
    commit(topic, "VERSION", "26.2.1\n", "VERSION: fixture upstream", 1700000000)
    commit(
        topic,
        f"{CODEC}/vn_protocol_driver.h",
        "/* This file is generated by venus-protocol git-70991d4c. */\n",
        "venus-protocol: fixture snapshot",
        1700000001,
    )
    commit(
        topic, f"{CODEC}/vn_protocol_driver_stale.h", "/* stale */\n",
        "venus-protocol: fixture stale header", 1700000002,
    )
    upstream_commit = run("git", "rev-parse", "HEAD", cwd=topic)
    upstream_tree = run("git", "rev-parse", "HEAD^{tree}", cwd=topic)
    commit(topic, "src/virtio/vulkan/vn_a.c", "a\n", "venus: fixture", 1700000010)
    commit(topic, "src/virtio/vulkan/vn_b.c", "b\n", "venus: fixture two", 1700000020)
    guest_tree = run("git", "rev-parse", "HEAD^{tree}", cwd=topic)
    guest_commit = run("git", "rev-parse", "HEAD", cwd=topic)
    export(fixture_scripts, topic, upstream_commit, source_root / GUEST_SERIES, "--tree")

    venus = android_root / "third_party/mesa-venus"
    (venus / "series").mkdir(parents=True)
    tools = android_root / "tools"
    tools.mkdir(parents=True)
    shutil.copy2(verifier, tools / "verify-mesa-venus-source.py")
    os.chmod(tools / "verify-mesa-venus-source.py", 0o755)
    shutil.copy2(verifier.with_name("pinned_source.py"), tools / "pinned_source.py")
    artifacts = source_root / "kernel/common/artifacts"
    artifacts.mkdir(parents=True)
    shutil.copy2(
        verifier.parents[3] / "kernel/common/artifacts/contract_checks.py",
        artifacts / "contract_checks.py",
    )
    protocol_tree = run("git", "rev-parse", "HEAD^{tree}", cwd=protocol)
    headers_tree = run("git", "rev-parse", "HEAD^{tree}", cwd=headers)
    (venus / "metadata.env").write_text(
        "# SPDX-License-Identifier: Apache-2.0\n"
        "MESA_VENUS_SOURCE_SCHEMA=2\n"
        f"MESA_VENUS_UPSTREAM_REPOSITORY='{REPOSITORY}'\n"
        "MESA_VENUS_UPSTREAM_RELEASE='mesa-26.2.1'\n"
        f"MESA_VENUS_UPSTREAM_COMMIT='{upstream_commit}'\n"
        f"MESA_VENUS_UPSTREAM_TREE='{upstream_tree}'\n"
        "MESA_VENUS_GUEST_EPOCH='source-22'\n"
        f"MESA_VENUS_GUEST_SERIES='{GUEST_SERIES}'\n"
        f"MESA_VENUS_GUEST_TREE='{guest_tree}'\n"
        f"MESA_VENUS_PROTOCOL_SERIES='{PROTOCOL_SERIES}'\n"
        f"MESA_VENUS_PROTOCOL_TREE='{protocol_tree}'\n"
        f"MESA_VENUS_VULKAN_HEADERS_TREE='{headers_tree}'\n"
        "MESA_VENUS_PATCH_BRANCH='kernarium-android17'\n"
        f"MESA_VENUS_FINAL_TREE='{guest_tree}'\n"
        "MESA_VENUS_DESTINATION='external/mesa3d-venus'\n"
        "MESA_VENUS_HAL_MODULE='vulkan.virtio'\n"
        "MESA_VENUS_LICENSE='MIT'\n"
    )

    # The protocol topic is whatever the generator writes from the pins.
    run(
        sys.executable, "-B", str(generator), "protocol",
        "--android-root", str(android_root), "--checkout", str(topic),
        "--protocol-source", str(protocol), "--vulkan-headers", str(headers),
    )
    run("git", "add", "-A", CODEC, cwd=topic)
    environment = os.environ.copy()
    environment["GIT_AUTHOR_DATE"] = "1700000030 +0000"
    environment["GIT_COMMITTER_DATE"] = "1700000030 +0000"
    run(
        "git", "commit", "-q", "-m", "Mesa Venus pair the generated protocol headers",
        cwd=topic, env=environment,
    )
    commit(
        topic,
        "src/virtio/vulkan/Android.bp",
        'cc_library_shared {\n    name: "vulkan.virtio",\n}\n',
        "Mesa Venus generated Soong port",
        1700000040,
    )
    return upstream_commit, guest_commit, protocol, headers, protocol_base


def refused(command: tuple[str, ...], expected: str, case: str) -> None:
    result = subprocess.run(
        command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True
    )
    if result.returncode == 0 or expected not in result.stdout:
        raise SystemExit(
            f"{case} was not refused with '{expected}': {result.stdout.strip()}"
        )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source-root", type=Path, required=True)
    args = parser.parse_args()
    source_root = args.source_root.resolve()
    tools = source_root / "android/lineage-24/tools"
    regenerator = tools / "regenerate-mesa-venus-patches.py"
    verifier = tools / "verify-mesa-venus-source.py"
    generator = tools / "generate-mesa-venus-port.py"

    with tempfile.TemporaryDirectory(prefix="mesa-venus-contract-") as temporary:
        root = Path(temporary)
        android_root = root / "android/lineage-24"
        topic = root / "topic"
        upstream_commit, guest_commit, protocol, headers, protocol_base = write_fixture(
            root, android_root, topic, verifier, generator
        )
        if (topic / CODEC / "vn_protocol_driver_stale.h").exists():
            raise SystemExit("the protocol generator kept a header it does not generate")
        command = (
            sys.executable,
            "-B",
            str(regenerator),
            "--android-root",
            str(android_root),
            "--topic-checkout",
            str(topic),
        )
        run(*command)
        fixture_verifier = android_root / "tools/verify-mesa-venus-source.py"
        verify = (
            sys.executable, "-B", str(fixture_verifier),
            "--android-root", str(android_root),
        )
        run(*verify)

        series = android_root / "third_party/mesa-venus/series"
        patches = sorted(series.glob("*.patch"))
        if len(patches) != 2:
            raise SystemExit(
                "the regenerator did not emit exactly the Android port commits"
            )
        listed = (series / "series.tsv").read_text()
        for name in (
            "Mesa-Venus-pair-the-generated-protocol-headers",
            "Mesa-Venus-generated-Soong-port",
        ):
            if name not in listed:
                raise SystemExit(f"Mesa Venus series lost patch: {name}")
        if "venus-fixture" in listed:
            raise SystemExit("the Android series absorbed the pinned guest series")
        metadata_path = android_root / "third_party/mesa-venus/metadata.env"
        final_tree = parse_env(metadata_path)["MESA_VENUS_FINAL_TREE"]
        if final_tree != run("git", "rev-parse", "HEAD^{tree}", cwd=topic):
            raise SystemExit("the regenerator did not record the topic tree")

        def materialize(aosp: Path) -> Path:
            (aosp / ".repo").mkdir(parents=True)
            destination = aosp / "external/mesa3d-venus"
            destination.parent.mkdir(parents=True)
            run(
                "git", "clone", "-q", "-b", "kernarium-android17",
                str(topic), str(destination),
            )
            run("git", "remote", "set-url", "origin", REPOSITORY, cwd=destination)
            run("git", "reset", "-q", "--hard", guest_commit, cwd=destination)
            return destination

        def apply(destination: Path) -> subprocess.CompletedProcess:
            return subprocess.run(
                (
                    sys.executable, "-B", str(root / "scripts/patch_series.py"),
                    "apply", "--repo", str(destination), "--series-dir", str(series),
                    "--expect-tree", final_tree,
                ),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
            )

        aosp = root / "aosp"
        checkout = materialize(aosp)
        if apply(checkout).returncode != 0:
            raise SystemExit("the Mesa Venus series did not replay to its recorded tree")
        run(*verify, "--aosp-source", str(aosp))
        metadata = parse_env(metadata_path)
        if metadata["MESA_VENUS_UPSTREAM_COMMIT"] != upstream_commit:
            raise SystemExit("the regenerator moved the pinned upstream commit")

        check = (
            sys.executable, "-B", str(generator), "protocol",
            "--android-root", str(android_root), "--checkout", str(checkout),
            "--protocol-source", str(protocol), "--vulkan-headers", str(headers),
            "--check",
        )
        run(*check)

        # A guest series that moves under the recorded pin must be refused.
        guest = root / GUEST_SERIES / "series.tsv"
        original_guest = guest.read_bytes()
        guest.write_bytes(original_guest.replace(
            f"tree\t{metadata['MESA_VENUS_GUEST_TREE']}".encode(),
            f"tree\t{metadata['MESA_VENUS_UPSTREAM_TREE']}".encode(),
        ))
        refused(verify, "guest Mesa series changed", "a moved guest Mesa series")
        guest.write_bytes(original_guest)

        metadata_text = metadata_path.read_text()

        def pin(key: str, value: str) -> None:
            metadata_path.write_text(
                metadata_text.replace(f"{key}='{metadata[key]}'", f"{key}='{value}'")
            )

        # A protocol topic the port has not been regenerated for is refused,
        # before and after the pin follows it. The generator refuses a source
        # past its pin, and reports the codec stale once the pin follows.
        protocol_dir = root / PROTOCOL_SERIES
        saved_protocol = {path.name: path.read_bytes() for path in protocol_dir.iterdir()}
        commit(
            protocol, "extensions.txt", "VK_one\nVK_two\n", "protocol: fixture two",
            1700000020,
        )
        export(root / "scripts", protocol, protocol_base, protocol_dir, "--tree")
        moved = run("git", "rev-parse", "HEAD^{tree}", cwd=protocol)
        refused(verify, "Venus protocol series changed", "a moved protocol series")
        refused(check, "not the pinned", "a protocol source past its pin")
        pin("MESA_VENUS_PROTOCOL_TREE", moved)
        refused(verify, "was not generated from the pinned", "a protocol pin bump alone")
        refused(check, "differs from the pinned generation", "a stale codec for a new pin")
        metadata_path.write_text(metadata_text)
        for path in protocol_dir.iterdir():
            path.unlink()
        for name, payload in saved_protocol.items():
            (protocol_dir / name).write_bytes(payload)
        run("git", "reset", "-q", "--hard", "HEAD~1", cwd=protocol)
        run(*verify)
        run(*check)

        # The same holds for the registry the codec is generated against.
        sources = root / VULKAN_SOURCES
        original_sources = sources.read_text()
        commit(
            headers, "registry/vk.xml", "<registry v='2'/>\n", "fixture registry two",
            1700000010,
        )
        registry = run("git", "rev-parse", "HEAD^{tree}", cwd=headers)
        sources.write_text(original_sources.replace(
            metadata["MESA_VENUS_VULKAN_HEADERS_TREE"], registry
        ))
        refused(verify, "Vulkan-Headers source changed", "a moved Vulkan-Headers pin")
        refused(check, "not the pinned", "a Vulkan-Headers source past its pin")
        pin("MESA_VENUS_VULKAN_HEADERS_TREE", registry)
        refused(verify, "was not generated from the pinned", "a registry pin bump alone")
        refused(
            check, "differs from the pinned generation", "a stale codec for a new registry"
        )
        metadata_path.write_text(metadata_text)
        sources.write_text(original_sources)
        run("git", "reset", "-q", "--hard", "HEAD~1", cwd=headers)

        (protocol / "untracked.txt").write_text("dirty\n")
        refused(check, "has local changes", "a dirty protocol source")
        (protocol / "untracked.txt").unlink()
        run(*verify)
        run(*check)

        stray = series / "stray.patch"
        stray.write_bytes(patches[0].read_bytes())
        refused(verify, "stray.patch", "a patch the series does not list")
        stray.unlink()

        altered = next(patch for patch in patches if "protocol-headers" in patch.name)
        original = altered.read_bytes()
        altered.write_bytes(
            original.replace(b'+#include "vn_protocol', b'+#include  "vn_protocol', 1)
        )
        if apply(materialize(root / "altered")).returncode == 0:
            raise SystemExit("the replay accepted a patch that changes the recorded tree")
        altered.write_bytes(original)

        metadata_before = metadata_path.read_bytes()
        series_before = (series / "series.tsv").read_bytes()
        (topic / "dirty.txt").write_text("dirty\n")
        rejected = subprocess.run(
            command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT
        )
        if rejected.returncode == 0:
            raise SystemExit("the regenerator accepted a dirty topic checkout")
        if metadata_path.read_bytes() != metadata_before:
            raise SystemExit("dirty-topic rejection changed Mesa Venus metadata")
        if (series / "series.tsv").read_bytes() != series_before:
            raise SystemExit("dirty-topic rejection changed the Mesa Venus series")

    print("Android 17 Mesa Venus source contract passed")


if __name__ == "__main__":
    main()
